<section class="page-head"><div><span class="eyebrow"><?=e(__('ui.finance'))?></span><h1><?=e(__('wallet.title'))?></h1></div></section><div class="wallet-hero"><span><?=e(__('wallet.balance'))?></span><strong><?=e(money($wallet['available_balance'],$wallet['currency']))?></strong><small><?=e(__('wallet.title'))?> · <?=e($wallet['status'])?></small></div><section class="section"><div class="section-head"><div><span class="eyebrow"><?=e(__('ui.ledger'))?></span><h2><?=e(__('common.details'))?></h2></div></div><?php if(!$transactions):?><div class="empty-state"><h2><?=e(__('wallet.empty'))?></h2></div><?php else:?><div class="table-wrap"><table><thead><tr><th>#</th><th><?=e(__('common.status'))?></th><th><?=e(__('common.price'))?></th><th><?=e(__('common.date'))?></th></tr></thead><tbody><?php foreach($transactions as $tx):?><tr><td><?=e($tx['transaction_number'])?></td><td><?=e($tx['status'])?></td><td class="<?=e($tx['direction'])?>"><?=e(($tx['direction']==='credit'?'+':'-').money($tx['amount'],$tx['currency']))?></td><td><?=e($tx['created_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
